  useEffect(() => {
    if (doc && typeof doc.terms === "string") setTermsDraft(doc.terms);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [doc?.id, doc?.terms]);

  if (!doc) {
    return (
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <Skeleton style={{ height: 200 }} />
