          >
            <img
              src={getTenantLogoUrl()}
              alt={
                (typeof window !== "undefined"
                  && window.localStorage
                  && window.localStorage.getItem("tenant_name"))
                || DEFAULT_LOGO_ALT
              }
              className="rounded-md shrink-0"
              style={{ height: 56, width: "auto",
                        border: `1px solid ${colors.border}` }}
